(function (SView) {
    let Commands;
    (function (Commands) {
        /**
         * @memberof SView.Commands
         * @extends SView.SCommand
         * @description 保存快照
         * @author ZQL
         */
        class SavePictureCommand extends SView.SCommand {
            /**
             * @public
             * @description 执行命令
             * @returns {number}
             */
            execute() {
                this.prepareDownload();
                return SView.CommandExecuteResult.Success;
            }
            /**
             * @protected
             * @description 预执行命令
             * @returns {number}
             */
            onPreExecute() {
                let parameters = M3D.Config.Parameters.getInstance();
                let isShowAxisID = parameters.getBoolParameter(M3D.Config.isShowAxisID);
                if (isShowAxisID) {
                    parameters.setBoolParameter(M3D.Config.isShowAxisID, false);
                }
                let scene = this.getScene();
                // 更新八叉树
                scene.getOctreeHandler().getOctree().update();
                let viewport = scene.getCurrentViewPort();
                let camera = viewport.getCamera();
                scene.getCurrentViewPort().getCullHelper().setAllowCuller(viewport, camera == null);
                return SView.CommandExecuteResult.Success;
            }
            /**
             * @public
             * @description 获取快照图片Url
             * @returns {string}
             */
            getCanvasUrl() {
                let url = this.frame.getCanvas().toDataURL('image/png');
                return url;
            }
            /**
             * @public
             * @description 截图
             * @param {boolean} isBackTrans 是否背景透明
             */
            snoptImage(isBackTrans) {
                // 记录之前的坐标轴和背景透明状态
                let axisOldState = M3D.Config.Parameters.getInstance().getBoolParameter(M3D.Config.isShowCoordinate);
                let transOldState = M3D.Config.Parameters.getInstance().getBoolParameter(M3D.Config.isBackTransparent);
                // 关闭坐标轴显示
                if (axisOldState) {
                    M3D.Config.Parameters.getInstance().setBoolParameter(M3D.Config.isShowAxisID, false);
                }
                // 背景透明
                if (!transOldState && isBackTrans) {
                    M3D.Config.Parameters.getInstance().setBoolParameter(M3D.Config.isBackTransparent, true);
                }
                //this.Draw();
                // 如果外部指定不使用blob或者不支持blob方式时，生成的是base64字符串
                //let url = this.renderCanvas.toDataURL('image/png');
                let url = this.frame.getCanvas().toDataURL('image/png');
                let imageName = new Date().getTime() + ".png";
                // 还原之前的坐标轴和背景透明状态
                if (axisOldState) {
                    M3D.Config.Parameters.getInstance().setBoolParameter(M3D.Config.isShowAxisID, axisOldState);
                }
                if (!transOldState) {
                    // 背景透明
                    M3D.Config.Parameters.getInstance().setBoolParameter(M3D.Config.isBackTransparent, transOldState);
                }
                return url;
            }
            /**
             * @private
             * @description 获取
             */
            prepareDownload() {
                let url = this.frame.getCanvas().toDataURL('image/png');
                let fileName = new Date().getTime() + ".png";
                this.download(url, fileName);
            }
            /**
             * @private
             * @description 下载
             * @param {string} url
             * @param {string} fileName
             */
            download(url, fileName) {
                if (this.myBrowser() === "Edge" || this.myBrowser() === "IE") {
                    //
                }
                else {
                    this.downloadByChrome(url, fileName);
                }
            }
            /**
             * @private
             * @description IE系列浏览器下载
             * @param {string} url
             * @param {string} fileName
             */
            downloadByIE(url, fileName) {
                // let arr = url.split(".");
                // let mime = arr[0].match(/:(.*?);/)[1];
                // let bstr = atob(arr[1]);
                // let n = bstr.length;
                // let u8arr = new Uint8Array(n);
                // while (n--) {
                //     u8arr[n] = bstr.charCodeAt(n);
                // }
                // let blob = new Blob([u8arr], { type: mime });
                // if ('msSaveOrOpenBlob' in navigator) {
                //     // window.navigator.msSaveOrOpenBlob(blob, fileName);
                //     return;
                // }
                // let eleLink = <HTMLAnchorElement>document.createElement("a");
                // eleLink.download = fileName;
                // $(eleLink).css("display", "none");
                // eleLink.href = URL.createObjectURL(blob);
                // document.body.appendChild(eleLink);
                // eleLink.click();
                // document.body.removeChild(eleLink);
            }
            /**
             * @private
             * @description 非IE浏览器下载
             * @param {string} url
             * @param {string} fileName
             */
            downloadByChrome(url, fileName) {
                let image = url.replace("image/png", "image/octet-stream");
                let save_link = document.createElementNS("http://www.w3.org/1999/xhtml", "a");
                save_link.href = image;
                save_link.download = fileName;
                let event = document.createEvent("MouseEvents");
                event.initMouseEvent("click", true, false, window, 0, 0, 0, 0, 0, false, false, false, false, 0, null);
                save_link.dispatchEvent(event);
            }
            /**
             * @private
             * @description 取得浏览器的userAgent字符串
             * @returns {string}
             */
            myBrowser() {
                let userAgent = navigator.userAgent; //取得浏览器的userAgent字符串
                let isOpera = userAgent.indexOf("Opera") > -1;
                if (isOpera) {
                    //判断是否Opera浏览器
                    return "Opera";
                }
                if (userAgent.indexOf("Edge") > -1) {
                    //判断是否Edge浏览器
                    return "Edge";
                }
                if (userAgent.indexOf("Firefox") > -1) {
                    //判断是否Firefox浏览器
                    return "FF";
                }
                if (userAgent.indexOf("Chrome") > -1) {
                    return "Chrome";
                }
                if (userAgent.indexOf("Safari") > -1) {
                    //判断是否Safari浏览器
                    return "Safari";
                }
                // if (!window.ActiveXObject || "ActiveXObject" in window) {
                //     return "IE";
                // }
                if (userAgent.indexOf("compatible") > -1 && userAgent.indexOf("MSIE") > -1 && !isOpera) {
                    return "IE";
                }
            }
            /**
             * @public
             * @description 获取参数是否完成准备
             * @returns {boolean}
             */
            getIsParametersComplete() {
                return true;
            }
        }
        Commands.SavePictureCommand = SavePictureCommand;
    })(Commands = SView.Commands || (SView.Commands = {}));
})(SView || (SView = {}));
