            commandEventHandle(commandManager, sCommand, commandEvent, commandEventArgs) {
                if (sCommand
                    && sCommand instanceof AutoRoamAnimationCommand
                    && commandEvent == SView.CommandEvent.Executed) {
                    commandManager.close(sCommand);
                }
            }
