                let loopPara = para.get(SetLoopPlayCommand.ifLoopPlay).value;
                if (this.animationPlayer) {
                    this.animationPlayer.setLoop(loopPara);
                }
                Commands.CommandLogger.COMMANDLOGD(M3D.END, Commands.CommandNames.SETLOOPPLAYCOMMAND, this.onExecute.name);
                return super.onExecute();
