                //如果配置项没有值 则添加
                let paras = super.getInputParas();
                if (!paras.contains(SetLoopPlayCommand.ifLoopPlay)) {
                    paras.add(SetLoopPlayCommand.ifLoopPlay, SView.CommandParameterType.BOOL, true, SView.IOParameterType.INPUT_PARAM, false);
                }
