        CreateClipPlaneCommand.YZSectionPercent = "YZSectionPercent"; //!< YZ剖面是否反向剖切                                                //!< ZX剖面是否反向剖切
        CreateClipPlaneCommand.ZXSectionPercent = "ZXSectionPercent"; //!<ZX剖面是否反向剖切
