            /**
             * @private
             * @description 显示剖切控制菜单
             */
            showSectionMenu() {
                let sectionMenuId = Commands.SectionMenu.BottomMenu.id;
                let uiMap = this.uiManager.find(sectionMenuId);
                if (uiMap) {
                    this.sectionMenu = uiMap.get(sectionMenuId);
                }
                if (this.sectionMenu) {
                    this.uiManager.showLabel(sectionMenuId);
                }
                else {
                    this.uiManager.load(SView.Commands.SectionMenu);
                    this.sectionMenu = this.uiManager.getElement(sectionMenuId);
                }
                if (this.sectionMenu) {
                    // 绑定弹窗点击事件
                    this.setOnClick();
                    let selectedShapeList = this.command.getInputParas()
                        .get(Commands.CreateClipPlaneCommand.SelectedShapeList).value;
                    let shapesSizeBtn = this.uiManager.getElement("addSectionBadge");
                    let shapesSize = selectedShapeList.length;
                    if (shapesSize > 0) {
                        shapesSizeBtn.show();
                        shapesSizeBtn.setContent(shapesSize.toString());
                    }
                    else {
                        shapesSizeBtn.hide();
                    }
                    ;
                }
            }
