(function (SView) {
    let Commands;
    (function (Commands) {
        /**
         * @memberof SView.Commands
         * @description: 爆炸命令
         */
        class ExplosionCommand extends SView.SCommand {
            constructor() {
                super(...arguments);
                this.explosiveAction = new SView.Actions.ExplosiveAction();
                this.explosiveBomAction = new SView.Actions.ExplosiveBomAction();
                this.modelsID = [];
                this.explosiveModels = []; //记录爆炸模型
                //爆炸方向（0 中心爆炸 1 沿X轴 2 沿Y轴）
                this.direction = 0;
                //爆炸等级（无.0.1.2.3.4.5）
                this.level = -1;
                //爆炸程度
                this.percent = 0;
                this.begin = true;
                // 参数初始化标注
                this.paraInit = false;
                // action 是否已经赋值过scene
                this.actionInitScene = false;
            }
            /**
             * @protected
             * @description  初始化
             * @returns  {number}
             */
            onInitialize() {
                let ret = super.onInitialize();
                if (!this.actionInitScene) {
                    let scene = this.getScene();
                    if (scene) {
                        this.explosiveAction.setScene(scene);
                        this.explosiveBomAction.setScene(scene);
                        this.explosiveBomAction.setExplosionModels(this.getScene().getTopModel().getChildren());
                    }
                    this.actionInitScene = true;
                }
                return ret;
            }
            /**
             * @protected
             * @description 命令执行前设置相关动作参数
             * @returns {number}
             */
            onPreExecute() {
                // 如果本次的爆炸参数和上一次完全相同 则不执行爆炸
                if (this.direction == this.preDirection &&
                    this.level == this.preLevel &&
                    this.percent == this.prePercent) {
                    return SView.CommandExecuteResult.ExecutedFailed;
                }
                return SView.CommandExecuteResult.Success;
            }
            /**
             * @public
             * @description 命令执行
             * @returns {number} 执行结果
             */
            onExecute() {
                //设置爆炸程度初始参数
                this.executeExplosion();
                return SView.CommandExecuteResult.Success;
            }
            /**
             * @description 业务逻辑执行完毕后
             * @returns  {number}
             */
            onExecuted() {
                if (this.level != this.preLevel) {
                    this.preLevel = this.level;
                }
                if (this.percent != this.prePercent) {
                    this.prePercent = this.percent;
                }
                if (this.direction != this.preDirection) {
                    this.preDirection = this.direction;
                }
                return super.onExecuted();
            }
            /**
            * @protected
            * @description 关闭命令相关操作
            * @returns {number}
            */
            onClose() {
                //this.explosiveAction.close();
                //this.actionInitScene = false;
                //this.begin = true;
                //this.explosiveAction.reset();
                return super.onClose();
            }
            /**
             * @public
             * @description 重置命令
             */
            reset() {
                this.actionInitScene = false;
                this.begin = true;
                this.explosiveAction.reset();
                this.explosiveBomAction.reset();
                this.percent = 0;
                this.view.reset();
            }
            /**
             * @public
             * @description 执行爆炸
             */
            executeExplosion() {
                this.getIsParametersComplete();
                if (!this.isNeedExecute())
                    return SView.CommandExecuteResult.Success;
                let selectedModels = this.handlerExplosiveModels();
                if (this.begin) {
                    this.explosiveAction.setExplosiveModel(selectedModels);
                    this.explosiveBomAction.setExplosionModels(selectedModels);
                    if (this.level == -1) {
                        this.explosiveAction.execute();
                    }
                    this.begin = false;
                }
                if (this.level != -1) {
                    this.updateExplosionModels(selectedModels);
                }
                let percent = this.percent / 50;
                if (this.level == -1) {
                    //整体爆炸
                    this.explosiveAction.setPercent(this.direction, percent);
                }
                else {
                    // 分级爆炸
                    if (this.explosiveBomAction.getDirection() != this.direction) {
                        this.explosiveBomAction.setDirection(this.direction);
                    }
                    if (this.explosiveBomAction.getPercent() != percent) {
                        this.explosiveBomAction.setPercent(percent);
                    }
                    if (this.explosiveBomAction.getLevel() != this.level) {
                        this.explosiveBomAction.setLevel(this.level);
                    }
                    this.explosiveBomAction.execute();
                }
                this.onExecuted();
                return SView.CommandExecuteResult.Success;
            }
            /**
             * @private
             * @description 处理选中模型
             */
            handlerExplosiveModels() {
                let models = [];
                if (this.level == -1) {
                    models = [this.getScene().getTopModel()];
                }
                else {
                    let shapes = this.getScene().getSelector().getAll();
                    // 当前没有选中模型 
                    if (shapes == null || shapes.length == 0) {
                        models = this.getScene().getTopModel().getChildren();
                    }
                    else {
                        for (let shape of shapes) {
                            if (shape instanceof M3D.Shapes.Model) {
                                models.push(shape);
                            }
                        }
                    }
                }
                return models;
            }
            /**
             * @private
             * @description 更新爆炸模型
             * @param {M3D.Shapes.Model[]} models
             */
            updateExplosionModels(models) {
                if (models == null || models.length == 0)
                    return;
                let isUpdate = false;
                for (let model of models) {
                    if (this.explosiveModels.indexOf(model) == -1) {
                        this.explosiveModels = models;
                        isUpdate = true;
                        break;
                    }
                }
                if (isUpdate) {
                    // if (this.level == -1) {
                    //     this.explosiveAction.setExplosiveModel(this.explosiveModels);
                    // } else {
                    this.explosiveBomAction.reset();
                    this.explosiveBomAction.setExplosionModels(this.explosiveModels);
                    // }
                }
            }
            /**
             * @private
             * @description 是否需要执行新的爆炸
             * @returns {boolean}
             */
            isNeedExecute() {
                return !(this.level == this.preLevel && this.percent == this.prePercent && this.direction == this.preDirection);
            }
            /**
             * @public
             * @description 获取参数
             * @returns {CommandParameters}
             */
            getInputParas() {
                let methodName = this.getInputParas.name;
                Commands.CommandLogger.COMMANDLOGD(M3D.START, Commands.CommandNames.EXPLOSIONCOMMAND, methodName);
                //如果配置项没有值 则添加
                let paras = super.getInputParas();
                if (paras == null)
                    paras = new SView.CommandParameters();
                if (this.paraInit) {
                    return paras;
                }
                paras.add(ExplosionCommand.ExplosionType, SView.CommandParameterType.INT, this.direction, SView.IOParameterType.INPUT_PARAM, false);
                paras.add(ExplosionCommand.ExplosionLevel, SView.CommandParameterType.INT, this.level, SView.IOParameterType.INPUT_PARAM, false);
                paras.add(ExplosionCommand.ExplosionValue, SView.CommandParameterType.INT, this.percent, SView.IOParameterType.INPUT_PARAM, false);
                paras.add(ExplosionCommand.ExplosionModel, SView.CommandParameterType.ARRAY, this.modelsID, SView.IOParameterType.UNKNOW, false);
                this.paraInit = true;
                Commands.CommandLogger.COMMANDLOGD(M3D.START, Commands.CommandNames.EXPLOSIONCOMMAND, methodName);
                return paras;
            }
            /**
             * @public
             * @description 获取参数是否完整 ，如果本次爆炸参数与上一次完全一致，则也认为参数不完整，以此终止命令执行
             * @returns  {boolean}
             */
            getIsParametersComplete() {
                //读取爆炸类型
                let type = this.inputParas.get(ExplosionCommand.ExplosionType).value;
                if (type != null) {
                    this.direction = type;
                }
                //读取爆炸等级
                let level = this.inputParas.get(ExplosionCommand.ExplosionLevel).value;
                if (level != null) {
                    this.level = level;
                }
                //读取爆炸模型
                let modelsID = this.inputParas.get(ExplosionCommand.ExplosionModel).value;
                if (modelsID != null) {
                    this.modelsID = modelsID;
                }
                //读取爆炸程度
                let percent = this.inputParas.get(ExplosionCommand.ExplosionValue).value;
                if (percent != null && this.percent != percent) {
                    this.percent = percent;
                }
                return !(this.direction == this.preDirection &&
                    this.level == this.preLevel &&
                    this.percent == this.prePercent);
            }
        }
        ExplosionCommand.ExplosionType = "ExplosionType"; //爆炸类型（模型中心.沿X轴.沿Y轴）
        ExplosionCommand.ExplosionLevel = "ExplosionLevel"; //爆炸等级（无.0.1.2.3.4.5）
        ExplosionCommand.ExplosionValue = "ExplosionValue"; // //爆炸程度
        ExplosionCommand.ExplosionModel = "ExplosionModel"; //爆炸模型ID
        Commands.ExplosionCommand = ExplosionCommand;
    })(Commands = SView.Commands || (SView.Commands = {}));
})(SView || (SView = {}));
var SView;
(function (SView) {
    let Commands;
    (function (Commands) {
        /**
          *@memberof SView.Commands
          *@description   爆炸命令View
          *@author	WZ
          *@date		2022-8-06
          *@version	1.0
          *@Copyright All Rights Reserved. Copyright (C) 2022 HOTEAMSOFT, Ltd
          */
        class ExplosionCommandView extends SView.SCommandView {
            constructor() {
                super(...arguments);
                this.explosionCommand = null;
                this.mainBottomMenuId = "mainBottomMenu";
                this.rightMenuId = "rightMenu";
                this.level = -1; // 爆炸级别
            }
            /**
             * @description 设置爆炸方向
             * @param {number} direction
             * @returns {number}
             */
            setDirection(direction) {
                if (this.direction == direction)
                    return;
                this.direction = direction;
                this.explosionCommand.getInputParas().update(Commands.ExplosionCommand.ExplosionType, direction);
                return this.explosionCommand.executeExplosion();
            }
            /**
             * @description 设置爆炸百分比
             * @param {number} percent
             * @returns {*}  {number}
             */
            setPercent(percent) {
                if (this.percent == percent)
                    return;
                this.percent = percent;
                this.explosionCommand.getInputParas().update(Commands.ExplosionCommand.ExplosionValue, percent);
                return this.explosionCommand.executeExplosion();
            }
            /**
             * @description 设置爆炸级别
             * @beta
             * @param {number} level 级别
             */
            setLevel(level) {
                if (this.level == level)
                    return;
                this.level = level;
                this.explosionCommand.getInputParas().update(Commands.ExplosionCommand.ExplosionLevel, level);
                if (this.percent != 0) {
                    // 更新slider
                    let input = document.getElementById("explosive_sliderBar");
                    input.value = "0";
                    input.style.backgroundSize = "0% 100%";
                    this.setPercent(0);
                }
                else {
                    this.explosionCommand.executeExplosion();
                }
            }
            /**
             * @public
             * @description 初始化
             * @returns  {number}
             */
            onInitialize() {
                if (this.command instanceof Commands.ExplosionCommand)
                    this.explosionCommand = this.command;
                super.onInitialize();
                this.showExplosionMenu();
                return SView.CommandExecuteResult.Success;
            }
            /**
             * @description 获取爆炸命令
             * @returns {ExplosionCommand}
             */
            getExplosionCommand() {
                return this.explosionCommand;
            }
            /**
             * @private
             * @description 显示爆炸菜单
             */
            showExplosionMenu() {
                this.uiManager = this.explosionCommand.frame.getUIManager();
                let explosionMenuId = Commands.ExplosiveMenu.BottomMenu.id;
                let uiMap = this.uiManager.find(explosionMenuId);
                if (uiMap != undefined) {
                    this.explosionMenu = uiMap.get(explosionMenuId);
                }
                if (this.explosionMenu) {
                    this.uiManager.showLabel(explosionMenuId);
                }
                else {
                    this.uiManager.load(SView.Commands.ExplosiveMenu);
                    this.explosionMenu = this.uiManager.getElement(explosionMenuId);
                }
                if (this.explosionMenu) {
                    // 绑定弹窗点击事件
                    this.setOnClick();
                }
            }
            /**
             * @private
             * @description 按键操作监听处理
             * */
            setOnClick() {
                let that = this;
                //let all = this.uiManager.find(ExplosionLevel.Select.id);
                // 爆炸模式
                let modeBtn = this.uiManager.getElement(Commands.ExplosionDirection.Button.id);
                let select = this.uiManager.getElement(Commands.ExplosionDirectionPopoverSelect.PopoverSelect.id);
                let modeBtns = select.getSubComponents();
                for (let i = 0; i < modeBtns.length; i++) {
                    let temp = modeBtns[i];
                    let btn = this.uiManager.find(temp.Button.id).get(temp.Button.id);
                    btn.eleLabel.onclick = function () {
                        that.setSelectModeItemHight(temp);
                        that.setDirection(i);
                    };
                }
                // 爆炸进度
                let progressBtn = this.uiManager.getElement(Commands.ExplosionSlider.Slider.id);
                progressBtn.setOnChangeEvent(function () {
                    let progress = Number(this.value);
                    let slider = that.uiManager.getElement(Commands.ExplosionSlider.Slider.id);
                    if (slider) {
                        slider.setValue(progress);
                    }
                    //let slider = document.getElementById(ExplosionLevel.Select.id);
                    //slider.style.backgroundSize = progress * 100 / 100 + "% 100%";
                    that.setPercent(progress);
                });
                //爆炸级别
                //let levelBtn: SView.Windows.Select = all.get(ExplosionLevel.Select.id);
                //levelBtn.setOnChangeEvent(function (ele) {
                //    let level = Number(ele.getValue());
                //    if (isNaN(level)) {
                //        return;
                //    }
                //    that.setLevel(level);
                //});
                // 退出爆炸
                this.exitBtn = document.getElementById(Commands.ExitExplosion.Button.id);
                this.exitBtn.onclick = function () {
                    // 退出爆炸确认框
                    that.uiManager.load(SView.Commands.ExplosiveExitDialog);
                    let confirmExitBtn = document.getElementById(Commands.ExplosiveExitDialogConfirm.Button.id);
                    // 确认框点击
                    confirmExitBtn.onclick = function () {
                        if (that.explosionCommand) {
                            that.explosionCommand.frame.getCommandsManager().close(that.explosionCommand);
                        }
                        that.hideExplosionMenu();
                        that.uiManager.removeLabel(SView.Commands.ExplosiveExitDialog.Dialog.id);
                        //发送界面退出的消息
                        let commandManager = that.explosionCommand.frame.getCommandsManager();
                        commandManager.sendExitMassage(that.explosionCommand);
                    };
                };
            }
            /**
             * @private
             * @description 隐藏爆炸菜单
             */
            hideExplosionMenu() {
                this.uiManager = this.explosionCommand.frame.getUIManager();
                let explosionMenuId = Commands.ExplosiveMenu.BottomMenu.id;
                let uiMap = this.uiManager.find(explosionMenuId);
                if (uiMap != undefined) {
                    this.explosionMenu = uiMap.get(explosionMenuId);
                }
                if (this.explosionMenu) {
                    this.uiManager.hideLabel(explosionMenuId);
                }
                // 显示底部菜单
                this.uiManager.showLabel(this.mainBottomMenuId);
                // 显示右侧菜单
                this.uiManager.showLabel(this.rightMenuId);
            }
            /**
             * @private
             * @description 设置选中项为高亮状态
             * @param {any} item 选中项
             */
            setSelectModeItemHight(item) {
                let id = item.Button.id;
                let menu = document.getElementById("explosive_global");
                menu.getElementsByClassName("SView-show")[0].classList.add("SView-hide");
                menu.getElementsByClassName("SView-show")[0].classList.remove("SView-show");
                let btnImg = menu.getElementsByTagName("img")[0];
                let dirs = document.getElementById(id).parentElement.parentElement.children;
                for (let i = 0; i < dirs.length; i++) {
                    let div = dirs[i].children[0];
                    div.style.backgroundColor = "";
                }
                SView.Windows.Button.highLightLabel(id);
                let currentImg = document.getElementById(id).getElementsByTagName("img")[0];
                btnImg.src = currentImg.src;
                btnImg.title = currentImg.title;
                // 隐藏气泡
                document.getElementById("explosiveSelect").classList.remove("SView-hide");
            }
            /**
             * @public
             * @description 重置
             */
            reset() {
                this.percent = 0;
                if (this.explosionCommand && this.explosionCommand.getInputParas()) {
                    this.explosionCommand.getInputParas().update(Commands.ExplosionCommand.ExplosionValue, 0);
                }
                // 更新slider
                let input = document.getElementById("explosive_sliderBar");
                if (input == null || input.value === "0")
                    return;
                input.value = "0";
                input.style.backgroundSize = "0% 100%";
            }
        }
        Commands.ExplosionCommandView = ExplosionCommandView;
    })(Commands = SView.Commands || (SView.Commands = {}));
})(SView || (SView = {}));
