(function (SView) {
    let Commands;
    (function (Commands) {
        /**
         * @memberof SView.Commands
         * @description 清空命令：包括批注、测量、剖切面等
         * @export
         * @class ClearCommand
         * @extends {SView.SCommand}
         */
        class ClearCommand extends SView.SCommand {
            /**
             * @constructor
             * Creates an instance of ClearCommand.
             * @param {string} name
             * @memberof ClearCommand
             */
            constructor(name) {
                super(name);
            }
            /**
             * @public
             * @description 根据类型清空数据
             * @return {boolean}
             * @memberof ClearCommand
             */
            clearShapes() {
                let shapeSet = this.frame.getViewer().getScene().getShapes();
                let isSuccess;
                switch (this.type) {
                    case M3D.Shapes.ShapeType.SECTION:
                        {
                            let sections = shapeSet.getShapes(M3D.Shapes.ShapeType.SECTION);
                            for (let iter = 0; iter < sections.length; ++iter) {
                                let section = sections[iter];
                                section.enablePlanes(false);
                                //  section.clearPlanes();
                            }
                            let sectionPlanes = shapeSet.getShapes(M3D.Shapes.ShapeType.SECTION_PLANE);
                            for (let iter = 0; iter < sectionPlanes.length; ++iter) {
                                let sectionPlane = sectionPlanes[iter];
                                sectionPlane.setEnable(false);
                                //  section.clearPlanes();
                            }
                            isSuccess = true;
                        }
                        break;
                    case M3D.Shapes.ShapeType.ANNOTATION_NOTE:
                    case M3D.Shapes.ShapeType.MEASURE_BASE:
                        {
                            let shapes = shapeSet.getShapes(this.type);
                            for (let shape of shapes) {
                                if (M3D.Shapes.ShapeHelper.isCorrelationModelView(shape, this.frame.getViewer().getScene())) {
                                    shape.setVisible(false);
                                }
                                else {
                                    shapeSet.removeShape(shape.getId());
                                }
                            }
                            if (this.type === M3D.Shapes.ShapeType.ANNOTATION_NOTE) {
                                let paintBrushs = shapeSet.getShapes(M3D.Shapes.ShapeType.THREED_GESTURE_NOTE);
                                for (let paintBrush of paintBrushs) {
                                    if (M3D.Shapes.ShapeHelper.isCorrelationModelView(paintBrush, this.frame.getViewer().getScene())) {
                                        paintBrush.setVisible(false);
                                    }
                                    else {
                                        shapeSet.removeShape(paintBrush.getId());
                                    }
                                }
                                let modelBoards = shapeSet.getShapes(M3D.Shapes.ShapeType.MODELBOARD);
                                for (let modelBoard of modelBoards) {
                                    if (M3D.Shapes.ShapeHelper.isCorrelationModelView(modelBoard, this.frame.getViewer().getScene())) {
                                        modelBoard.setVisible(false);
                                    }
                                    else {
                                        shapeSet.removeShape(modelBoard.getId());
                                    }
                                }
                            }
                            isSuccess = true;
                            //isSuccess = shapeSet.clearShapes(this.type);
                            break;
                        }
                }
                this.frame.getViewer().getScene().refresh();
                return isSuccess;
            }
        }
        Commands.ClearCommand = ClearCommand;
    })(Commands = SView.Commands || (SView.Commands = {}));
})(SView || (SView = {}));
