            parseImportConfig(value) {
                let ret = false;
                if (value && M3D.Utility.DecideHelper.isJson(value)) {
                    let configureReader = new SView.FrameConfigureReader();
                    let retMap = new Map();
                    configureReader.parse(value, retMap);
                    if (retMap.size > 0) {
                        if (M3D.Config.ConfigFileParameters.check(retMap)) {
                            SView.FrameConfigure.getInstance().initConfig(retMap);
                            Commands.CommandLogger.COMMANDLOGI(SView[SView.UIManager.languageInfo].languageObj.
                                ImportConfig.Import_Config_Success, "Configure", "");
                            //强制触发渲染
                            //this.getScene().getRender().getRender().onRenderHandler();
                            ret = true;
                        }
                        else {
                            ret = false;
                        }
                    }
                }
                else {
                    Commands.CommandLogger.COMMANDLOGI(SView[SView.UIManager.languageInfo].languageObj.
                        ImportConfig.Import_Config_Fail, "Configure", "");
                    ret = false;
                }
                return ret;
            }
