            /**
             * @private
             * @description 设置背景颜色
             * @param {string} key
             * @param {string} topColorStr
             * @param {string} bottomColorStr
             * @memberof OptionCommandView
             */
            setBackgroudColor(key, topColorStr, bottomColorStr) {
                //console.log("---------key------" + key + "---------color------" + colorStr);
                let topColor = new M3D.M3DMath.Color();
                let bottomColor = new M3D.M3DMath.Color();
                topColor.hexToRgb(topColorStr);
                bottomColor.hexToRgb(bottomColorStr);
                this.optionCommand.setBackgroudColor(topColor, bottomColor);
                //先取消选中所有
                let settingItem = JSON.parse(JSON.stringify(Commands.SystemCommonBackgroundColorItem));
                let btns = settingItem.SettingItem.subComponents;
                for (let i = 0; i < btns.length; i++) {
                    let btn = this.uiManager.getElement(btns[i].Button.id);
                    if (btn) {
                        btn.setHighLight(false);
                    }
                }
                //当前选中
                let curbtn = this.uiManager.getElement(key);
                if (curbtn) {
                    curbtn.setHighLight(true);
                }
            }
