            /**
             * @description 是否显示虚拟摇杆
             * @private
             * @param {boolean} isShow
             * @memberof OptionCommandView
             */
            isShowJoyStick(isShow) {
                let joyStickVirtualRockerItem = this.optionCommand.frame.getUIManager().getElement(Commands.JoystickVirtualRocker.VirtualRocker.id);
                let joyStickUpAndDownItem = this.optionCommand.frame.getUIManager().getElement(Commands.JoystickUpAndDown.UpAndDown.id);
                if (isShow) {
                    //同时打开摇杆
                    if (!joyStickVirtualRockerItem) {
                        this.optionCommand.frame.getUIManager().load(JSON.parse(JSON.stringify(Commands.JoystickVirtualRocker)));
                    }
                    else {
                        this.optionCommand.frame.getUIManager().showLabel(Commands.JoystickVirtualRocker.VirtualRocker.id);
                    }
                    if (!joyStickUpAndDownItem) {
                        this.optionCommand.frame.getUIManager().load(JSON.parse(JSON.stringify(Commands.JoystickUpAndDown)));
                    }
                    else {
                        this.optionCommand.frame.getUIManager().showLabel(Commands.JoystickUpAndDown.UpAndDown.id);
                    }
                    this.setJoyStickEvent(true);
                }
                else {
                    this.optionCommand.frame.getUIManager().hideLabel(Commands.JoystickVirtualRocker.VirtualRocker.id);
                    this.optionCommand.frame.getUIManager().hideLabel(Commands.JoystickUpAndDown.UpAndDown.id);
                    this.setJoyStickEvent(false);
                }
            }
            /**
             * @description 给虚拟摇杆添加事件
             * @private
             * @param {boolean} isSet
             * @memberof OptionCommandView
             */
            setJoyStickEvent(isSet) {
                let that = this;
                let joyStickVirtualRockerItem = that.optionCommand.frame.getUIManager().getElement(Commands.JoystickVirtualRocker.VirtualRocker.id);
                let joyStickUpAndDownItem = that.optionCommand.frame.getUIManager().getElement(Commands.JoystickUpAndDown.UpAndDown.id);
                let ser = SView.ServiceManager.getInstance().getService(SView.Services.ServiceType.RoamService, SView.Services);
                let upAndDownMouseMove = function (isUp, distance) {
                    if (ser) {
                        //ser.getRoamAction().moveUpAndDown(isUp ? -distance : distance);
                        if (!ser.getIsUpAndDown()) {
                            ser.setIsUpAndDown(true);
                        }
                        ser.getUpOrDownMap().isUp = isUp;
                        ser.getUpOrDownMap().distance = distance;
                    }
                };
                let upAndDownMouseUp = function (isUp, distance) {
                    if (ser) {
                        if (ser.getIsUpAndDown()) {
                            ser.setIsUpAndDown(false);
                        }
                    }
                };
                let virtualRockerMouseMove = function (toSend) {
                    if (ser) {
                        if (!ser.getIsVirtualRocker()) {
                            ser.setIsVirtualRocker(true);
                        }
                        let theta = Number(toSend.angle.radian);
                        let dis = Number(toSend.distance);
                        ser.getVirtualRockerMap().strSpeed = dis * Math.sin(theta) / 80.0;
                        ser.getVirtualRockerMap().sidSpeed = dis * Math.cos(theta) / 80.0;
                    }
                };
                let virtualRockerMouseUp = function () {
                    if (ser) {
                        if (ser.getIsVirtualRocker()) {
                            ser.setIsVirtualRocker(false);
                        }
                    }
                };
                if (isSet) {
                    joyStickUpAndDownItem.setOnMove(upAndDownMouseMove);
                    joyStickUpAndDownItem.setOnMouseup(upAndDownMouseUp);
                    joyStickVirtualRockerItem.setOnMove(virtualRockerMouseMove);
                    joyStickVirtualRockerItem.setOnMouseup(virtualRockerMouseUp);
                    if (ser) {
                        ser.statrTimer();
                    }
                }
                else {
                    if (ser) {
                        ser.stopTimer();
                    }
                    if (joyStickUpAndDownItem) {
                        joyStickUpAndDownItem.setOnMove(null);
                        joyStickUpAndDownItem.setOnMouseup(null);
                    }
                    if (joyStickVirtualRockerItem) {
                        joyStickVirtualRockerItem.setOnMove(null);
                        joyStickVirtualRockerItem.setOnMouseup(null);
                    }
                }
            }
            /**
             * @description 弹出选择颜色的对话框
             * @private
             * @param {string} key
             * @param {string} colorBtnId
             * @param {boolean} isSys
             * @memberof OptionCommandView
             */
            showColorSelectDialog(key, colorBtnId, isSys) {
                let colorSelectDialog = this.uiManager.getElement(Commands.ColorSelectDialog.Dialog.id);
                if (colorSelectDialog != null) {
                    this.uiManager.removeLabel(Commands.ColorSelectDialog.Dialog.id);
                }
                let colorDialog = JSON.parse(JSON.stringify(Commands.ColorSelectDialog));
                this.uiManager.load(colorDialog);
                this.colorpicker = this.uiManager.getElement(Commands.Colorpicker.Colorpicker.id);
                if (this.colorpicker) {
                    //初始化选中的颜色
                    let colorcus = new M3D.M3DMath.Color();
                    if (!isSys) {
                        colorcus = this.optionCommand.getDocParameter(key, "color");
                    }
                    else {
                        colorcus = this.optionCommand.getParameter(key, "color");
                    }
                    let rgbcus = {
                        r: Math.round(colorcus.r * 255),
                        g: Math.round(colorcus.g * 255),
                        b: Math.round(colorcus.b * 255),
                    };
                    this.colorpicker.setValue(rgbcus);
                }
                let that = this;
                let confirmAction = function () {
                    let hex = that.colorpicker.getValue();
                    let selectcolor = new M3D.M3DMath.Color();
                    selectcolor.hexToRgb(hex);
                    //保存变量
                    that.optionCommand.setParameter(key, selectcolor, isSys);
                    //更新按钮的颜色
                    let colorBtn = that.uiManager.getElement(colorBtnId);
                    if (colorBtn) {
                        colorBtn.setBGColor(hex);
                    }
                    //成功提示
                    let text = SView[SView.UIManager.languageInfo].languageObj.Prompt.SuccessfulOperation;
                    switch (colorBtnId) {
                        case Commands.clipPlaneColorBtn.Button.id: //剖面颜色
                            that.optionCommand.setClipPlaneColor(selectcolor);
                            break;
                        case Commands.clipLineColorBtn.Button.id: //剖面线颜色
                            that.optionCommand.setClipLineColor(selectcolor);
                            break;
                        case Commands.clipCapColorBtn.Button.id: //盖面颜色
                            that.optionCommand.setClipCapColor(selectcolor);
                            break;
                        case Commands.selectedColorBtn.Button.id: //选中颜色
                            that.optionCommand.setSelectedColor(selectcolor);
                            break;
                    }
                    that.showMessage(text);
                    that.removeColorSelectDialog();
                };
                let cancelAction = function () {
                    that.removeColorSelectDialog();
                };
                // 绑定确认按钮点击事件
                let confirmBtn = document.getElementById(Commands.ColorSelectConfirmBtn.Button.id);
                confirmBtn.onclick = confirmAction;
                let cacnelmBtn = document.getElementById(Commands.ColorSelectCancelBtn.Button.id);
                cacnelmBtn.onclick = cancelAction;
            }
            /**
             * @description 删除选择颜色的对话框
             * @private
             * @memberof OptionCommandView
             */
            removeColorSelectDialog() {
                let colorSelectDialog = this.uiManager.getElement(Commands.ColorSelectDialog.Dialog.id);
                if (colorSelectDialog != null) {
                    this.uiManager.removeLabel(Commands.ColorSelectDialog.Dialog.id);
                    this.colorpicker = null;
                }
            }
