            /**
             * @public
             * @description 导入配置
             * @memberof OptionCommandView
             */
            importConfig() {
                let that = this;
                let fileinput = document.getElementById(SView.Commands.FileInput.Input.id);
                const reader = new FileReader();
                reader.onload = function () {
                    //得到文件的数据
                    let value = reader.result;
                    if (that.optionCommand.parseImportConfig(value)) {
                        //console.log("----------读取成功----------");
                        fileinput.value = "";
                        that.initSystemSetting();
                        let text = SView[SView.UIManager.languageInfo].languageObj.Alert.Alert_Reload;
                        that.showMessage(text);
                        that.optionCommand.getScene().refresh();
                    }
                    else {
                        fileinput.value = "";
                        //console.error("----------读取失败----------");
                        let text = SView[SView.UIManager.languageInfo].languageObj.ImportConfig.Import_Config_Fail;
                        that.showMessage(text);
                    }
                };
                reader.readAsText(fileinput.files[0], "utf8");
                //let ret = this.optionCommand.importConfig();
                //if (ret) {
                //    //提示导入成功
                //    console.log("-----------导入成功--------------");
                //    document.getElementById(SView.Commands.FileInput.Input.id).setAttribute("value","");
                //} else {
                //    //提示导入失败
                //    console.error("-----------导入失败--------------");
                //}
            }
