            /**
             * @public
             * @description 是否开启调试
             * @param {boolean} value
             * @memberof OptionCommandView
             */
            openOrCloseDebug(value) {
                let ele = document.getElementById(Commands.SystemTabs.Tabs.id).querySelectorAll(".SView-vertical-tab");
                let debugEle = null;
                let dataClass = null;
                for (var i = 0; i < ele.length; i++) {
                    dataClass = ele[i].getAttribute("data-class");
                    if (dataClass == Commands.SystemDebug.List.id) {
                        debugEle = ele[i];
                        break;
                    }
                }
                if (value) {
                    debugEle.style.display = "flex";
                    this.uiManager.getElement(dataClass).show();
                }
                else {
                    debugEle.style.display = "none";
                    this.uiManager.getElement(dataClass).hide();
                }
            }
