            /**
             * @private
             * @description 设置预显类型（点、线、面）
             * @param {PreviewType} type 需要预览的类型
             */
            setPreviewType(type) {
                switch (type) {
                    case Commands.PreviewType.Point:
                        this.setShapeType(M3D.Shapes.ShapeType.POINT);
                        break;
                    case Commands.PreviewType.Line:
                        this.setShapeType(M3D.Shapes.ShapeType.POLYLINE);
                        break;
                    case Commands.PreviewType.SurFace:
                        this.setShapeType(M3D.Shapes.ShapeType.FACE);
                        break;
                }
            }
            /**
             * @private
             * @description 设置过滤类型
             * @param {number} pickShapeType 过滤类型
             */
            setShapeType(pickShapeType) {
                let paras = this.measureDiametreCommand.scene.getCurrentViewPort().getParameter();
                paras.setNumberParameter(M3D.Config.ConfigKeys.ITEM_PICK_SHAPE_TYPE, pickShapeType);
            }
            /**
             * @protected
             * @description 创建点
             * @param {M3D.Inputs.Input} sender
             * @param {M3D.Inputs.MouseEventArgs | M3D.Inputs.TouchEventArgs} e
             * @returns {number} 执行结果
             */
            createrPoint(sender, e) {
                let methodName = this.createRadius.name;
                Commands.CommandLogger.COMMANDLOGD(M3D.START, Commands.CommandViewNames.DIAMETREMEASURE, methodName);
                let state = SView.CommandExecuteResult.Failure;
                if (this.getCurrentParameter() == Commands.MeasureDiametreCommand.firstGeometry) {
                    //let shape: M3D.Shapes.Shape = this.measureDiametreCommand.scene.getCurrentViewPort().getPickShape(e.position[0], e.position[1], M3D.Shapes.ShapeType.EDGE);
                    let paras = this.measureDiametreCommand.getInputParas();
                    let shape = sender.getViewport().getPickShape(e.position[0], e.position[1], M3D.Shapes.ShapeType.EDGE);
                    //if (!shape) {
                    //    paras.add(MeasureDiametreCommand.firstPosition, CommandParameterType.VECTOR3, null);
                    //    this.measureDiametreCommand.preview();
                    //    return state;
                    //}
                    let posV = new M3D.M3DMath.Vector2(e.position[0], e.position[1]);
                    let result = sender.getViewport().getPickFeaturePoint(posV);
                    let fristPoint = result[0];
                    let isFeature = result[1];
                    if (fristPoint && isFeature === 2) {
                        paras.add(Commands.MeasureDiametreCommand.firstPosition, SView.CommandParameterType.VECTOR3, fristPoint);
                        state = this.measureDiametreCommand.preview();
                    }
                    else {
                        paras.add(Commands.MeasureDiametreCommand.firstPosition, SView.CommandParameterType.VECTOR3, null);
                        this.measureDiametreCommand.preview();
                        state = SView.CommandExecuteResult.Failure;
                    }
                }
                else if (this.getCurrentParameter() == Commands.MeasureDiametreCommand.secondGeometry) {
                    let paras = this.measureDiametreCommand.getInputParas();
                    let shape = sender.getViewport().getPickShape(e.position[0], e.position[1], M3D.Shapes.ShapeType.EDGE);
                    if (!shape) {
                        paras.add(Commands.MeasureDiametreCommand.secondPosition, SView.CommandParameterType.VECTOR3, null);
                        this.measureDiametreCommand.preview();
                        return state;
                    }
                    let posV = new M3D.M3DMath.Vector2(e.position[0], e.position[1]);
                    //let fristPoint: M3D.M3DMath.Vector3 = sender.getViewport().getPickFeaturePoint(posV);
                    let result = sender.getViewport().getPickFeaturePoint(posV);
                    let fristPoint = result[0];
                    let isFeature = result[1];
                    if (fristPoint && isFeature === 2) {
                        paras.add(Commands.MeasureDiametreCommand.secondPosition, SView.CommandParameterType.VECTOR3, fristPoint);
                        state = this.measureDiametreCommand.preview();
                    }
                    else {
                        paras.add(Commands.MeasureDiametreCommand.secondPosition, SView.CommandParameterType.VECTOR3, null);
                        this.measureDiametreCommand.preview();
                        state = SView.CommandExecuteResult.Failure;
                    }
                }
                else if (this.getCurrentParameter() == Commands.MeasureDiametreCommand.thirdGeometry) {
                    let paras = this.measureDiametreCommand.getInputParas();
                    let shape = sender.getViewport().getPickShape(e.position[0], e.position[1], M3D.Shapes.ShapeType.EDGE);
                    if (!shape) {
                        paras.add(Commands.MeasureDiametreCommand.thirdPosition, SView.CommandParameterType.VECTOR3, null);
                        this.measureDiametreCommand.preview();
                        return state;
                    }
                    let posV = new M3D.M3DMath.Vector2(e.position[0], e.position[1]);
                    //let fristPoint: M3D.M3DMath.Vector3 = sender.getViewport().getPickFeaturePoint(posV);
                    let result = sender.getViewport().getPickFeaturePoint(posV);
                    let fristPoint = result[0];
                    let isFeature = result[1];
                    if (fristPoint && isFeature === 2) {
                        paras.add(Commands.MeasureDiametreCommand.thirdPosition, SView.CommandParameterType.VECTOR3, fristPoint);
                        state = this.measureDiametreCommand.preview();
                    }
                    else {
                        paras.add(Commands.MeasureDiametreCommand.thirdPosition, SView.CommandParameterType.VECTOR3, null);
                        this.measureDiametreCommand.preview();
                        state = SView.CommandExecuteResult.Failure;
                    }
                }
                Commands.CommandLogger.COMMANDLOGD(M3D.END, Commands.CommandViewNames.DIAMETREMEASURE, methodName);
                return state;
            }
            /**
             * @private
             * @description 设置圆弧和圆心预显
             * @param {M3D.Inputs.Input} sender
             * @param {M3D.Inputs.MouseEventArgs | M3D.Inputs.TouchEventArgs} e
             * @returns {number} 执行结果
             */
            setCircleCenter(sender, e) {
                // 生在所在点的弧线，若生成，则高亮。鼠标移动之后，盘点当前鼠标点是否在预显的弧线上，若是保持当前弧线高亮，否则，删除之前的弧线并生成新的弧线。圆心需要预显。
                let methodName = this.setCircleCenter.name;
                Commands.CommandLogger.COMMANDLOGD(M3D.START, Commands.CommandViewNames.DIAMETREMEASURE, methodName);
                let state = SView.CommandExecuteResult.Failure;
                if (this.getCurrentParameter() == Commands.MeasureDiametreCommand.firstGeometry) {
                    if (!M3D.Config.ViewPortParameters.getInstance().getBoolParameter(M3D.Config.isShowEdge)) {
                        let shape = this.measureDiametreCommand.scene.getCurrentViewPort().getPickShape(new M3D.M3DMath.Vector2(e.position[0], e.position[1]), M3D.Shapes.ShapeType.ONLY_MODEL);
                        if (shape && shape.getShapeType() == M3D.Shapes.ShapeType.MODEL) {
                            let model = shape;
                            this.getCommand().getScene().getLoader().getEdges(model, M3D.Shapes.ShapeType.EDGE, M3D.Shapes.GeoFeatureEnum.FEATURE_TYPE_LINE);
                        }
                    }
                    let shape = this.measureDiametreCommand.scene.getCurrentViewPort().getPickShape(new M3D.M3DMath.Vector2(e.position[0], e.position[1]), M3D.Shapes.ShapeType.EDGE, M3D.Shapes.GeoFeatureEnum.FEATURE_TYPE_UNKNOWN);
                    //this.measureDiametreCommand.scene.getSelector().add(shape);
                    let paras = this.measureDiametreCommand.getInputParas();
                    if (shape) {
                        let fristPoint = sender.getViewport().getPickPoint(e.position[0], e.position[1], false, true);
                        paras.add(Commands.MeasureDiametreCommand.firstPosition, SView.CommandParameterType.VECTOR3, fristPoint);
                        paras.add(Commands.MeasureDiametreCommand.firstModelID, SView.CommandParameterType.STRING, shape.getId().toString());
                        paras.add(Commands.MeasureDiametreCommand.firstGeometry, SView.CommandParameterType.OBJECT, shape);
                        state = this.measureDiametreCommand.preview();
                    }
                    else {
                        paras.add(Commands.MeasureDiametreCommand.firstPosition, SView.CommandParameterType.VECTOR3, null);
                        paras.add(Commands.MeasureDiametreCommand.firstModelID, SView.CommandParameterType.STRING, "-1");
                        paras.add(Commands.MeasureDiametreCommand.firstGeometry, SView.CommandParameterType.OBJECT, null);
                        state = SView.CommandExecuteResult.Failure;
                    }
                    this.measureDiametreCommand.preSelectShape();
                }
                Commands.CommandLogger.COMMANDLOGD(M3D.END, Commands.CommandViewNames.DIAMETREMEASURE, methodName);
                return state;
            }
