            /**
             * @private
             * @description 显示命令提示框
             * @param {boolean} type 是否
             * @param {string} [content] 具体提示内容
             */
            showTipMessage(type, content) {
                let messageId = Commands.BtnMessageDialog.Message.id;
                if (type) {
                    Commands.BtnMessageDialog.Message.content = content;
                    let uiManager = this.measureDiametreCommand.frame.getUIManager();
                    let messageMap = uiManager.find(messageId);
                    let message;
                    if (messageMap != undefined) {
                        message = messageMap.get(messageId);
                    }
                    // 判断提示信息是否已创建
                    if (message) {
                        // 若提示信息已创建，显示标签
                        message.setContent(content);
                        message.show();
                    }
                    else {
                        // 若提示信息未创建，创建标签
                        this.measureDiametreCommand.frame.getUIManager().load(Commands.BtnMessageDialog);
                        message = this.measureDiametreCommand.frame.getUIManager().allElements.get(messageId);
                    }
                }
                else {
                    this.measureDiametreCommand.frame.getUIManager().removeLabel(messageId);
                }
            }
