                Commands.CommandLogger.COMMANDLOGD(M3D.START, Commands.CommandNames.DISTANCEMEASURE, methodName);
                //如果配置项没有值 则添加
                let paras = super.getInputParas();
                if (paras == null)
                    paras = new SView.CommandParameters();
                Commands.CommandLogger.COMMANDLOGD(M3D.END, Commands.CommandNames.DISTANCEMEASURE, methodName);
