                if (this.createPropertyAction == null) {
                    this.createPropertyAction = new SView.Actions.CreatePropertyAction();
                }
                if (this.createPropertyAction === null) {
                    return SView.CommandExecuteResult.Failure;
                }
                let paras = super.getInputParas();
                let selectedShape = paras.get(MeasurePropertyCommand.selectedShape).value;
                this.createPropertyAction.setScene(this.scene);
                let attrStr = this.createPropertyAction.getProperty(selectedShape);
                if (attrStr != "") {
                    view.showPropertyDialog(attrStr);
                    result = SView.CommandExecuteResult.Success;
                }
                return result;
