                let configParas = this.getScene().getCurrentViewPort().getParameter();
                configParas.setNumberParameter(M3D.Config.ConfigKeys.ITEM_PICK_SHAPE_TYPE, this.pickShapeType);
                configParas.setNumberParameter(M3D.Config.ConfigKeys.ITEM_PICK_GEO_TYPE, this.pickGeoType);
                this.setInputParas(null);
