                //如果配置项没有值 则添加
                let paras = super.getInputParas();
                if (paras == null)
                    paras = new SView.CommandParameters();
                if (this.paraInit)
                    return paras;
                this.paraInit = true;
                //填充命令专有参数及默认值
                paras.add(ShapeSetCommand.shapeSetNameKey, SView.CommandParameterType.STRING, null, SView.IOParameterType.INPUT_PARAM);
                paras.add(ShapeSetCommand.shapeSetKey, SView.CommandParameterType.OBJECT, null, SView.IOParameterType.INPUT_PARAM);
                paras.add(ShapeSetCommand.shapesKey, SView.CommandParameterType.ARRAY, [], SView.IOParameterType.INPUT_PARAM);
