(function (SView) {
    let Commands;
    (function (Commands) {
        /**
         * @memberof SView.Commands
         * @extends SView.SCommand
         * @description 选择移动类型
         * @author ZQL
         */
        class MoveTypeCommand extends SView.SCommand {
            constructor() {
                super(...arguments);
                this.preX = 0;
                this.preY = 0;
                this.scale = 0; // 屏幕倍率
            }
            /**
             * @public
             * @description 设置移动类型
             * @param {SView.Actions.MoveStyle} style
             */
            setMoveStyle(style) {
                this.moveStyle = style;
                if (this.moveTypeAction) {
                    this.moveTypeAction.moveStyle = style;
                }
            }
            /**
             * @public
             * @description 获取移动类型
             * @returns {SView.Actions.MoveStyle}
             */
            getMoveStyle() {
                return this.moveStyle;
            }
            /**
             * @public
             * @description 获取移动方向
             * @returns {SView.Actions.MoveDirection}
             */
            getMoveDirection() {
                return this.moveDirection;
            }
            /**
             * @public
             * @description 设置移动方向
             * @param {SView.Actions.MoveDirection} value
             */
            setMoveDirection(value) {
                this.moveDirection = value;
                if (this.moveTypeAction) {
                    this.moveTypeAction.moveDirection = value;
                }
            }
            /**
             * @protected
             * @description 命令初始化
             * @returns {CommandExecuteResult}
             */
            onInitialize() {
                // this.setHandlerType(M3D.Inputs.InputHandlerType.INPUT_HANDLER_DRAGGER);
                this.scale = 1;
                this.moveTypeAction = new SView.Actions.MoveTypeAction();
                this.moveTypeAction.scene = this.getScene();
                this.moveDirection = SView.Actions.MoveDirection.MoveDirectionPlane;
                this.moveStyle = SView.Actions.MoveStyle.MoveStyleTranslation;
                let msg = new M3D.Utility.M3DMessage(Commands.CommandNames.MOVETYPECOMMAND, "onInitialize");
                this.frame.getCommandsManager().send(msg);
                return SView.CommandExecuteResult.Success;
            }
            /**
             * @public
             * @description 命令执行
             * @returns {number}
             */
            OnExecute() {
                return SView.CommandExecuteResult.Success;
            }
            /**
             * @protected
             * @description 结束命令
             * @returns {number}
             */
            onClose() {
                this.setHandlerType(M3D.Inputs.InputHandlerType.INPUT_HANDLER_COMMON);
                let selector = this.getScene().getSelector();
                // 退出命令时，需不需要清空选中模型 ?
                selector.clear();
                this.getScene().refresh();
                let msg = new M3D.Utility.M3DMessage(Commands.CommandNames.MOVETYPECOMMAND, "onClose");
                this.frame.getCommandsManager().send(msg);
                return SView.CommandExecuteResult.Success;
            }
            /**
             * @public
             * @description 设置输入处理类型
             * @param {M3D.Inputs.InputHandlerType} type
             */
            setHandlerType(type) {
                if (this.getScene() != null) {
                    let allViewport = this.getScene().getViewPorts().getAllViewport();
                    for (let element of allViewport) {
                        let viewprot = Array.from(element.values())[0];
                        viewprot.getInput().inputHandlerType = type;
                    }
                    this.moveTypeAction.setHandlerType(type);
                }
            }
            /**
             * @public
             * @description 设置初始位置
             * @param {number[]} position
             */
            setOriPosition(position) {
                if (position == null || position.length != 2) {
                    return;
                }
                this.preX = position[0];
                this.preY = position[1];
                if (!this.inputPoint) {
                    this.inputPoint = new M3D.Inputs.InputPoint();
                }
                this.inputPoint.currentPos[0] = this.preX;
                this.inputPoint.currentPos[1] = this.preY;
                this.inputPoint.oldPos[0] = this.preX;
                this.inputPoint.oldPos[1] = this.preY;
            }
            /**
             * @public
             * @description 鼠标左键按下并移动
             * @param {M3D.Inputs.Input} sender
             * @param {M3D.Inputs.MouseEventArgs} e
             * @returns {boolean}
             */
            onMouseLeftButtonMove(sender, e) {
                let position = [e.position[0], e.position[1]];
                this.inputPoint.currentPos = position;
                switch (this.moveStyle) {
                    case SView.Actions.MoveStyle.MoveStyleTranslation:
                        // 平移
                        this.executeTranslation(sender, e);
                        break;
                    case SView.Actions.MoveStyle.MoveStyleRotate:
                        // 旋转
                        this.executeRotate(sender, e);
                        break;
                    case SView.Actions.MoveStyle.MoveStyleScale:
                        // 缩放
                        this.executeScale(sender, e);
                        break;
                }
                this.inputPoint.oldPos = position;
                let x = position[0], y = position[1];
                this.preX = x;
                this.preY = y;
                return false;
            }
            /**
             * @private
             * @description 执行模型平移
             * @param {M3D.Inputs.Input} sender
             * @param {M3D.Inputs.MouseEventArgs} e
             */
            executeTranslation(sender, e) {
                let trackBall = sender.getTrackBall();
                trackBall.onePointMove(this.inputPoint);
                let moveVec = trackBall.motionMatrix.Translation();
                let camera = sender.getViewport().getCamera();
                let viewMat = camera.getViewMatrix().Clone().Transpose().ToMatrix3().Inverse();
                moveVec = new M3D.M3DMath.Vector3(viewMat.Multiply(moveVec));
                let move;
                switch (this.moveDirection) {
                    case SView.Actions.MoveDirection.MoveDirectionPlane: {
                        move = new M3D.M3DMath.Vector3(moveVec);
                        break;
                    }
                    case SView.Actions.MoveDirection.MoveDirectionX:
                        move = new M3D.M3DMath.Vector3(moveVec.x, 0.0, 0.0);
                        break;
                    case SView.Actions.MoveDirection.MoveDirectionY:
                        move = new M3D.M3DMath.Vector3(0, moveVec.y, 0.0);
                        break;
                    case SView.Actions.MoveDirection.MoveDirectionZ:
                        move = new M3D.M3DMath.Vector3(0, 0, moveVec.z);
                        break;
                }
                this.moveTypeAction.executeAction(this.moveStyle, move);
            }
            /**
             * @private
             * @description 执行模型旋转
             * @param {M3D.Inputs.Input} ender
             * @param {M3D.Inputs.MouseEventArgs} e
             */
            executeRotate(sender, e) {
                let trackBall = sender.getTrackBall();
                trackBall.onePointRotate(this.inputPoint);
                let camera = sender.getViewport().getCamera();
                let mainQuat = trackBall.motionMatrix.Rotation().Clone();
                let viewMat = camera.getViewMatrix().Clone().Transpose().ToMatrix3();
                let tempQuat = new M3D.M3DMath.Quaternion(viewMat);
                tempQuat.Normalize();
                mainQuat = (tempQuat.Inverse().Multiply(mainQuat)).Multiply(tempQuat);
                let roratteQuat;
                switch (this.moveDirection) {
                    case SView.Actions.MoveDirection.MoveDirectionPlane:
                        roratteQuat = mainQuat;
                        break;
                    case SView.Actions.MoveDirection.MoveDirectionX:
                        roratteQuat = new M3D.M3DMath.Quaternion(mainQuat.w, mainQuat.x, 0.0, 0.0);
                        roratteQuat.Normalize();
                        break;
                    case SView.Actions.MoveDirection.MoveDirectionY:
                        roratteQuat = new M3D.M3DMath.Quaternion(mainQuat.w, 0.0, mainQuat.y, 0.0);
                        roratteQuat.Normalize();
                        break;
                    case SView.Actions.MoveDirection.MoveDirectionZ:
                        roratteQuat = new M3D.M3DMath.Quaternion(mainQuat.w, 0.0, 0.0, mainQuat.z);
                        roratteQuat.Normalize();
                        break;
                }
                this.moveTypeAction.executeAction(this.moveStyle, roratteQuat);
            }
            /**
             * @private
             * @description 执行模型缩放
             * @param {M3D.Inputs.Input} sender
             * @param {M3D.Inputs.MouseEventArgs} e
             */
            executeScale(sender, e) {
                let trackBall = sender.getTrackBall();
                let rect = sender.getViewport().getRect();
                // 缩放值参考 之前的计算方法
                // 直接使用TrackBall的scaleFactor 有问题
                let temp = (rect.max.y - this.preY) / (rect.max.y - this.inputPoint.currentPos[1]);
                let scaleFactor = 1 / temp;
                let scaleVec;
                switch (this.moveDirection) {
                    case SView.Actions.MoveDirection.MoveDirectionPlane:
                        //  等比例缩放
                        scaleVec = new M3D.M3DMath.Vector3(scaleFactor, scaleFactor, scaleFactor);
                        break;
                    case SView.Actions.MoveDirection.MoveDirectionX:
                        scaleVec = new M3D.M3DMath.Vector3(scaleFactor, 1.0, 1.0);
                        break;
                    case SView.Actions.MoveDirection.MoveDirectionY:
                        scaleVec = new M3D.M3DMath.Vector3(1.0, scaleFactor, 1.0);
                        break;
                    case SView.Actions.MoveDirection.MoveDirectionZ:
                        scaleVec = new M3D.M3DMath.Vector3(1.0, 1.0, scaleFactor);
                        break;
                }
                this.moveTypeAction.executeAction(this.moveStyle, scaleVec);
            }
        }
        Commands.MoveTypeCommand = MoveTypeCommand;
    })(Commands = SView.Commands || (SView.Commands = {}));
})(SView || (SView = {}));
