                this.resetMoveTypeUI();
                let btnImg = menu.getElementsByTagName("img")[0];
                SView.Windows.Button.highLightLabel(Commands.Translation.Button.id);
                let currentImg = document.getElementById(Commands.Translation.Button.id).getElementsByTagName("img")[0];
                btnImg.src = currentImg.src;
                btnImg.title = currentImg.title;
                let all = this.uiManager.find(Commands.TranslationMode.Button.id);
                let btns = Array.from(all.values());
                for (let btn of btns) {
                    btn.eleLabel.style.backgroundColor = "";
                }
