                    if (!sender.getViewport().getScene().getShapes().getShape(this.downPoint.getId())) {
                        sender.getViewport().getScene().getShapes().addShape(this.downPoint);
                    }
                    this.downPoint.setPosition(point);
                    sender.getViewport().getScene().getShapes().updateShape(this.downPoint);
