        class RoamCommand extends SView.SCommand {
            //keyMap = {};//按键映射表
            /**
             * @constructor
             * @description 构造函数
             * @param {FrameMain} frame
             */
            constructor(frame) {
                super(frame, Commands.CommandNames.ROAM_COMMAND);
                // 命令执行状态
                this.executeState = SView.CommandExecuteResult.Failure;
                //速度 0.25X、0.5X、0.75X、1X、2X、4X、6X、8X、10X
                this.roamSpeed = 1;
                //向上方向 +X -X +Y -Y +Z -Z
                //upward = "+Y";
                this.upward = 2;
                //视野大小 5°10°15°20°30°40°50°60°70°80°90°100°110°120°130°140°150°
                this.angle = 40;
                //是否允许鼠标操作
                this.mouseswitch = true;
                this.oldOrthographic = true; //之前平行投影状态，退出时需要还原
                //this.priority = CommandPriority.Priority_1;
            }
            /**
             * @public
             * @description 获取参数
             * @returns {CommandParameters}
             */
            getInputParas() {
                Commands.CommandLogger.COMMANDLOGD(M3D.START, Commands.CommandNames.ROAM_COMMAND, this.getInputParas.name);
                //如果配置项没有值 则添加
                let paras = super.getInputParas();
                if (paras == null)
                    paras = new SView.CommandParameters();
                //paras.add(
                //    RoamCommand.Direction,
                //    CommandParameterType.STRING,
                //    M3D.Config.ViewPortParameters.getInstance().getStringParameter(M3D.Config.verticalAxis) != null ?
                //        M3D.Config.ViewPortParameters.getInstance().getStringParameter(M3D.Config.verticalAxis) : this.upward,
                //);
                paras.add(RoamCommand.Direction, SView.CommandParameterType.INT, M3D.Config.ViewPortParameters.getInstance().getNumberParameter(M3D.Config.verticalAxis) != null ?
                    M3D.Config.ViewPortParameters.getInstance().getNumberParameter(M3D.Config.verticalAxis) : this.upward);
                paras.add(RoamCommand.FieldSize, SView.CommandParameterType.INT, M3D.Config.ViewPortParameters.getInstance().getNumberParameter(M3D.Config.fieldSize) != null ?
                    M3D.Config.ViewPortParameters.getInstance().getNumberParameter(M3D.Config.fieldSize) : this.angle);
                paras.add(RoamCommand.Speed, SView.CommandParameterType.INT, M3D.Config.ViewPortParameters.getInstance().getNumberParameter(M3D.Config.roamingSpeed) != null ?
                    M3D.Config.ViewPortParameters.getInstance().getNumberParameter(M3D.Config.roamingSpeed) : this.roamSpeed);
                paras.add(RoamCommand.isMouseswitch, SView.CommandParameterType.BOOL, M3D.Config.ViewPortParameters.getInstance().getBoolParameter(Commands.CommandConfig.isMouseswitch) != null ?
                    M3D.Config.ViewPortParameters.getInstance().getBoolParameter(Commands.CommandConfig.isMouseswitch) : this.mouseswitch);
                Commands.CommandLogger.COMMANDLOGD(M3D.START, Commands.CommandNames.ROAM_COMMAND, this.getInputParas.name);
                return paras;
            }
            /**
             * @protected
             * @description 命令执行
             * @returns {CommandExecuteResult} 执行结果
             */
            onExecute() {
                let result = SView.CommandExecuteResult.Failure;
                //执行创建逻辑 使用Action创建
                let serviceManager = SView.ServiceManager.getInstance();
                let ser = serviceManager.getService(SView.Services.ServiceType.RoamService, SView.Services);
                M3D.Utility.M3DMessageCenter.getCenter().subscribe(this.view, ser);
                if (ser.getState() == SView.ServiceState.Started) {
                    ser.stop();
                }
                else {
                    let paras = this.getInputParas();
                    let size = paras.get(RoamCommand.FieldSize).value;
                    let speed = paras.get(RoamCommand.Speed).value;
                    let dir = paras.get(RoamCommand.Direction).value;
                    let mouseswitch = paras.get(RoamCommand.isMouseswitch).value;
                    //ser.setCameraFov(size);
                    ser.setUpDirection(this.convertDir(dir));
                    //ser.setSpeed(speed);
                    ser.setIsMouseswitch(mouseswitch);
                    ser.start();
                    ser.setCameraFov(size);
                }
                result = SView.CommandExecuteResult.Success;
                //this.oldOrthographic = this.getScene().getCurrentViewPort().getCamera().isOrthographic();
                //this.scene.getCurrentViewPort().getInput().setInputHandlerType(M3D.Inputs.InputHandlerType.INPUT_HANDLER_WALKTHROUGH);
                //this.scene.getCurrentViewPort().getCamera().setOrthographic(false);
                //if (this.roamAction == null) {
                //    this.roamAction = new Actions.RoamAction();
                //    //设置视口
                //    this.roamAction.setScene(this.getScene());
                //    this.roamAction.setViewport(this.getScene().getCurrentViewPort());
                //}
                //let paras: CommandParameters = this.getInputParas();
                //let size: number = paras.get(RoamCommand.FieldSize).value;
                //let speed: number = paras.get(RoamCommand.Speed).value;
                //let dir: number = paras.get(RoamCommand.Direction).value;
                //this.roamAction.setUpDirection(this.convertDir(dir));
                //this.roamAction.setCameraFov(size);
                this.frame.getCommandsManager().close(this);
                return result;
            }
            /**
             * @protected
             * @description 结束命令
             * @returns {number}
             */
            onClose() {
                //this.scene.getCurrentViewPort().getCamera().setOrthographic(this.oldOrthographic);
                //this.scene.getCurrentViewPort().getInput().setInputHandlerType(M3D.Inputs.InputHandlerType.INPUT_HANDLER_COMMON);
                return super.onClose();
            }
            /**
             *  @protected
             * @description 执行批注操作（命令的执行过程，每移动一次鼠标触发一次）
             * @returns {number} 执行结果
             */
            onProcess() {
                Commands.CommandLogger.COMMANDLOGD(M3D.START, Commands.CommandNames.BASEANNOTATION, this.onProcess.name);
                let result = SView.CommandExecuteResult.Failure;
                result = this.onExecute();
                Commands.CommandLogger.COMMANDLOGD(M3D.END, Commands.CommandNames.BASEANNOTATION, this.onProcess.name);
                return result;
            }
            /**
             * @private
             * @description 设置向上方向
             * @param {number} dir
             * @returns {M3D.M3DMath.Vector3}
             */
            convertDir(dir) {
                let upDirection = new M3D.M3DMath.Vector3(0, 1, 0);
                switch (dir) {
                    case 0:
                        upDirection = new M3D.M3DMath.Vector3(1, 0, 0);
                        break;
                    case 1:
                        upDirection = new M3D.M3DMath.Vector3(-1, 0, 0);
                        break;
                    case 2:
                        upDirection = new M3D.M3DMath.Vector3(0, 1, 0);
                        break;
                    case 3:
                        upDirection = new M3D.M3DMath.Vector3(0, -1, 0);
                        break;
                    case 4:
                        upDirection = new M3D.M3DMath.Vector3(0, 0, 1);
                        break;
                    case 5:
                        upDirection = new M3D.M3DMath.Vector3(0, 0, -1);
                        break;
                }
                return upDirection;
            }
        }
        RoamCommand.Direction = "Direction";
