            initModelViewList() {
                let that = this;
                //let defaultModelViewIdMap: Map<string, any> = new Map<string, any>;//视图列表中默认视图id
                let defaultOption; //默认视图
                this.uiManager = this.command.frame.getUIManager();
                this.onInitialize();
                //获取视图列表模块
                let sviewViewPanel = this.uiManager.getElement("sview_view_panel");
                //如果存在则不再重新加载视图
                if (sviewViewPanel.getAllSubComponents().childElementCount > 0) {
                    return;
                }
                let options = [];
                for (let modelview of this.modelViewList) {
                    let name = modelview.getName();
                    let id = SView.VIEWPREFIX + modelview.getId();
                    let option = JSON.parse(JSON.stringify(Commands.ModelViewListOption));
                    option.ViewItem.id = id;
                    option.ViewItem.name = name;
                    option.ViewItem.time = modelview.getProperty("createTime");
                    option.ViewItem.author = modelview.getProperty("creator");
                    if (modelview.getProperty("isServerView") === "1") { //在线视图
                        option.ViewItem.fileId = modelview.getProperty("fileId");
                        option.ViewItem.serverId = modelview.getProperty("serverId");
                        option.ViewItem.isServerView = modelview.getProperty("isServerView");
                        var isInitView = modelview.getIsInitView(); //是否是默认视图
                        option.ViewItem.isActivated = isInitView;
                        //this.showViewListCommand.setDefaultModelView(modelview);//设置默认视图
                        if (modelview.getProperty("image")) {
                            option.ViewItem.imgSrc = modelview.getProperty("image");
                        }
                        if (isInitView) { //在线视图有默认的，则设置默认视图id，模型视图不再展示模型在线视图
                            defaultOption = option;
                        }
                    }
                    else { //模型视图
                        option.ViewItem.isServerView = "0";
                        var image = modelview.getProperty("image");
                        if (image) { //有图片
                            option.ViewItem.imgSrc = image;
                            if (modelview.getProperty("parentModel")) {
                                option.ViewItem.name = "(" + name + ")";
                                option.ViewItem.isSubModelView = true;
                            }
                        }
                        else { //无图片
                            if (modelview.getProperty("parentModel")) {
                                option.ViewItem.name = "(" + name + ")";
                                option.ViewItem.isSubModelView = true;
                            }
                        }
                        if (modelview.getProperty("parentModel")) {
                            if (!M3D.Config.Parameters.getInstance().getBoolParameter(M3D.Config.isShowChildView)) {
                                continue;
                            }
                            let viewName = "(" + modelview.getName() + ")";
                            option.ViewItem.isSubModelView = true;
                            var modelName = modelview.getProperty("parentModelsName");
                            option.ViewItem.view_model_name = modelName;
                            option.ViewItem.name = modelName + viewName;
                        }
                        if (defaultOption && defaultOption.ViewItem.isServerView === "1") { //如果在线视图已经存在默认视图，则取消模型视图的默认视图
                            option.ViewItem.isActivated = false;
                        }
                        else {
                            var isInitView = modelview.getIsInitView(); //是否是默认视图
                            option.ViewItem.isActivated = isInitView;
                            if (isInitView) {
                                if (defaultOption) {
                                    //如果存在多个模型视图是默认视图，多个默认视图以最后一个为准
                                    function isBigEnough(element, index, array) {
                                        return (element === defaultOption);
                                    }
                                    let oldOption = options.filter(isBigEnough);
                                    if (oldOption) {
                                        oldOption[0].ViewItem.isActivated = false;
                                    }
                                    //defaultOption.isActivated = false;
                                }
                                defaultOption = option;
                            }
                            else {
                                option.ViewItem.isActivated = false;
                            }
                        }
                    }
                    //if (option.ViewItem.isActivated) {//如果是默认视图则插入为第一个
                    //    //options.unshift(option);
                    //    //this.showViewListCommand.setDefaultModelView(modelview);//设置默认视图
                    //} else {
                    options.push(option);
                    //}
                }
                if (defaultOption) {
                    options.splice(options.indexOf(defaultOption), 1);
                    options.unshift(defaultOption);
                }
                sviewViewPanel.loadOrUpdateView(options, "sview_view_panel");
                //视图切换事件
                sviewViewPanel.setOnClickEvent(function (sviewViewPanel) {
                    that.onModelViewChange(that, sviewViewPanel);
                });
                //视图编辑事件
                sviewViewPanel.setEditOnClickEvent(function (sviewViewPanel) {
                    that.onModelViewRename(that, sviewViewPanel);
                });
                //视图删除事件
                sviewViewPanel.setRemoveOnClickEvent(function (sviewViewPanel) {
                    that.onModelViewRemove(that, sviewViewPanel);
                });
                //视图设置默认视图事件
                sviewViewPanel.setTagOnClickEvent(function (sviewViewPanel) {
                    that.onModelViewSetDefault(that, sviewViewPanel);
                });
                //如果有默认视图，则优先显示默认视图的模型--模型优先加载，则不切换默认视图
                //if (defaultOption) {
                //    that.onModelViewChange(that, null,defaultOption.ViewItem.id);
                //}
            }
